questionvariables.text:
/* Function to round values to a given number of decimal places. */
rnd(x,dp):=float(round(x*10^dp)/10^dp);


/* Randomise the first bin centre.
   The remaining five centres increase by 1. */
xstart:rand(8)+4;
xvals:makelist(xstart+i,i,0,5);


/* Six equal-width classes, each of width 1. */
xmin:xstart-1/2;
xmax:xstart+11/2;
bounds:makelist(xmin+i,i,0,6);


/* Place the normal distribution exactly in the middle
   of the displayed histogram range. */
mean:xstart+5/2;


/* Keep the standard deviation fairly small so that
   very few observations fall outside the displayed range. */
sd:1.2;


/* Generate 100 normally distributed observations,
   rounded to 3 decimal places. */
n:100;

dun:makelist(
    rnd(float(quantile_normal(rand(1.0),mean,sd)),3),
    i,1,n
);


/* Clamp any observations which fall outside the
   displayed histogram range. */
data:map(
    lambda([x],
        if x<xmin then xmin
        elseif x>xmax then xmax
        else x
    ),
    dun
);


/* Sort the observations for calculating the percentile. */
sdata:sort(data);


/*
   Estimate the sample 75th percentile by interpolation.

   Using the position:
       1 + (n-1)*0.75

   For n=100 this is 75.25, so Q3 lies one quarter
   of the way between observations 75 and 76.
*/
qpos:1+(n-1)*3/4;
qlo:floor(qpos);
qfrac:qpos-qlo;

ta:sdata[qlo]+qfrac*(sdata[qlo+1]-sdata[qlo]);


/* Count the number of observations in each histogram class. */
barheights:makelist(
    length(
        sublist(
            data,
            lambda([x],
                if i<6 then
                    is(x>=bounds[i] and x<bounds[i+1])
                else
                    is(x>=bounds[i] and x<=bounds[i+1])
            )
        )
    ),
    i,1,6
);

/* Find the maximum bar height. */
maxheight:barheights[1];

for i:2 thru 6 do (
    if barheights[i]>maxheight then
        maxheight:barheights[i]
);

/* Scale the tallest bar to height 5. */
plotheights:makelist(
    5*barheights[i]/maxheight,
    i,1,6
);
